def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
        16-bit unsigned integer.

        NOTE: This does not pad with zeroes if the data isn't 16 bits long.
        """
    return (self.read(2) >> 8) << 8 | self.read(2)

