import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        timestamps = {}

        @wraps(func)
        def memoized_func(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in timestamps:
                cached_at = timestamps[key]
                if cached_at + ttl > timer():
                    result = cache[key]
                    cache[key] = None
                    timestamps[key] = timer()
                    return result

            result = func(*args, **kwargs)
            indicesToRemove = []

            for key, value in cache.items():
                if value is None:
                    cache.pop(key)
                else:
                    timestamps[key] = timer()
                    if isinstance(value, tuple):
                        diff = timer() - value[0]
                    else:
                        diff = value
                    if diff > ttl:
                        indicesToRemove.append(key)

            for key in indicesToRemove:
                cache.pop(key)
                timestamps.pop(key)

            size = len(cache)
            if size >= maxsize and maxsize != 0:
                oldest_key = min(timestamps, key=timestamps.get)
                cache.pop(oldest_key)
                timestamps.pop(oldest_key)

            cache[key] = result
            timestamps[key] = timer()

            return result

        return memoized_func

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.

    :param maxsize: maximum number of items to cache
    :param typed: whether to hash the arguments before caching
    :return: a wrapper function that caches its inputs and outputs
    """
    def cache_blocking(f):
        def wrapper(key):
            if key in cache:
                return cache[key]
            result = f(key)
            cache[key] = result
            return result
        return wrapper
    if typed:
        cache = {}
        return cache_blocking
    else:
        cache = []
        def wrapper(key):
            if key in cache:
                return cache.pop(cache.index(key))
            result = f(key)
            cache.append(key)
            if len(cache) > maxsize:
                cache.pop(0)
            return result
        return wrapper

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""

    if key not in self:
        self[key] = default

    return self[key]

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    return self.get(key, default)

