def _legacy_mergeOrderings(orderings):
    reordered = []
    current_set = None

    for ordering in orderings:
        for entry in ordering:
            if isinstance(entry, str):
                # Handle strings by appending
                reordered.append(entry)
            elif isinstance(entry, int):
                # Already in sorted order
                reordered.append(entry)
            else:
                # Handle nested orderings
                sub reordered = _legacy_mergeOrderings([entry])
                reordered.extend(sub reordered)

        if current_set:
            for index, entry in enumerate(reordered):
                if isinstance(entry, str):
                    if entry in current_set:
                        # Append string if it is in the current set
                        reordered.insert(index, entry)
        else:
            # Start a new set
            current_set = set(reordered)

    return reordered

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # normalize the sequence
    if isinstance(sequence, Declaration):
        sequence = (sequence,)

    # expand all simple types and collections
    for i, arg in enumerate(sequence):
        if isinstance(arg, Interface):
            continue
        elif isinstance(arg, Instance):
            continue
        elif isinstance(arg, Typed):
            sequence[i] = arg.spec
        elif isinstance(arg, Sequence):
            sequence[i] = arg.type
        elif isinstance(arg, Union):
            sequence[i] = (tuple(arg.types), sequence[i].quantity)
        elif isinstance(arg, Tuple):
            sequence[i] = (arg.type, sequence[i].quantity)
        elif isinstance(arg, Type):
            sequence[i] = arg.type
        elif isinstance(arg, Primitive):
            sequence[i] = arg

    return sequence

