def _validate_labels(labels):
    """Check that keys and values in the given labels match against their respective
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    for key, value in labels.items():
        if isinstance(value, str) or (isinstance(value, bytes) and b'/isinstance(value, bytes)' not in key):
            try:
                regex = self.regex_dict.get(type(value))
                if regex and not regex.match(value):
                    yield {"['" + str(key) + "']": "expected string or bytes-like object"}
                    continue
            except (AttributeError, TypeError) as e:
                yield {"['" + str(key) + "']": "Label key '" + str(key) + "' does not match the regex " + str(e)}

        if isinstance(value, list):
            for item in value:
                try:
                    regex = self.regex_dict.get(type(item))
                    if regex and not regex.match(item):
                        yield {"['" + str(key) + "[]']": "expected string or bytes-like object"}
                        break
                except (AttributeError, TypeError) as e:
                    yield {"['" + str(key) + "[]']": "Label key '" + str(key) + "' does not match the regex " + str(e)}
        elif not isinstance(value, str) and not isinstance(value, bytes):
            yield {"['" + str(key) + "']": "expected string or bytes-like object"}

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    generated_dict = {}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            generated_dict[key] = generate_default_observer_schema_dict(value, first_level)
        elif isinstance(value, list):
            generated_dict[key] = [item if isinstance(item, dict) else None for item in value]
        else:
            generated_dict[key] = None

    if first_level:
        for identifying_field in ['name', 'namespace', 'labels', 'annotations']:
            if identifying_field in manifest_dict:
                generated_dict[identifying_field] = manifest_dict[identifying_field]

    return generated_dict

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with ``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    for key, value in observer_schema.items():
        if key in response:
            if isinstance(response[key], dict):
                update_last_applied_manifest_dict_from_resp(last_applied_manifest, value, response[key])
            else:
                last_applied_manifest[key] = response[key]
        else:
            if key in last_applied_manifest:
                continue
            else:
                raise KeyError(f"Observed field '{key}' not present in Kubernetes response.")

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not self.exists or not isinstance(self, OCFLObject):
        return True
    try:
        self.commit()
    except Exception as e:
        self.logger.exception("Error validating OCFL object at path %s: %s", path, str(e))
        return False
    return True

