        """Check all digests in manifest that are needed are present and used."""

        # Check that all digests in manifest_files are present
        for digest in digest_files:
            if digest not in self.digests_used:
                raise KeyError('Digest "{}" not found in manifest.'.format(digest))

        # Check that all digests in digests_used are present
        for digest in digests_used:
            if digest in self.digests:
                raise KeyError('Digest "{}" already present in manifest.'.format(digest))

    def __init__(self, manifest_files, digests_used):
        """Initialize the package with a set of manifest files and a set of digests that are needed."""
        self.digests = set(manifest_files)
