def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    for logical_path, state in inventory.items():
        if state > version:
            continue

        content_files = set()
        for file_path, version_path in state.items():
            if file_path > version_path:
                continue
            content_files.add(file_path)

        logical_path_map[logical_path] = content_files

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        raise ValueError("Fixity block is empty")
    if isinstance(fixity, str):
        fixity = {'files': [fixity]}
    elif not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary with a 'files' key")
    if not 'files' in fixity:
        raise ValueError("Missing 'files' key in fixity block")
    if not isinstance(fixity['files'], list):
        raise ValueError("Files key in fixity block must be a list")
    if not all(isinstance(file, str) for file in fixity['files']):
        raise ValueError("All elements in the files list must be strings")

    manifest_files = set(manifest_files) if manifest_files else set()
    for file in fixity['files']:
        if file not in manifest_files:
            raise FileNotFoundError("File " + file + " not found in manifest")

