import xml.etree.ElementTree as ET

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """
    package_data = {}

    for root, dirs, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                xml_file_path = os.path.join(root, file)
                xml_tree = ET.parse(xml_file_path)
                root_element = xml_tree.getroot()

                xml_base = root_element.tag.splitlines()[0].split('}')[0]
                if xml_base in package_data:
                    package_data[xml_base]['files'].append(xml_file_path)
                else:
                    package_data[xml_base] = {
                        'files': [xml_file_path],
                        'contains': [root_element.tag.splitlines()[0].split('}')[0]]
                    }

    return package_data

