def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    output = []
    current = None

    for expr in args:
        if expr.type == "And":
            if expr.args[0] is current:
                current = expr.args[1]
            else:
                output.append(expr)
        elif expr.type == "Or":
            if expr.args[0] is current and expr.args[1] is current:
                current = expr.args[1]
            else:
                output.append(expr)
        else:
            if current is None or expr.type == "~And" and current.type == "~Or":
                current = expr
                output.append(expr)
            else:
                output.append(expr)

    return output

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        def decorator(func):
            if not hasattr(self, '_handlers'):
                self._handlers = {}

            if hook not in self._handlers:
                self._handlers[hook] = []

            self._handlers[hook].append(func)

            return func

        return decorator

