def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version or version == "_latest":
        return "latest"

    zeros = len(version)
    postfix = version[zeros:]

    if postfix.isdigit():
        num = int(postfix) + 1
        if num == 10:
            return "latest"
        if num == 0:
            return version
        zeros = len(str(num))
        if zeros < len(postfix):
            postfix = postfix[:zero]
        return "latest" + ("0" * (zeros - len(postfix))) + postfix
    else:
        return "latest"

