def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = []
    for subparser_name, parser in subparsers.items():
        if parser.prog in unparsed_arguments:
            parsed_args[subparser_name] = parser.parse_args(unparsed_arguments[subparser_name], namespace=dict())
            remaining_args.extend(unparsed_arguments[subparser_name][::2])
            parsed_args[subparser_name].parsed_args.extend(unparsed_arguments[subparser_name][1::2])

    return parsed_args, remaining_args

