import logging
from pathlib import Path

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configurations = {}
    errors = []

    for config_filename in config_filenames:
        config_path = Path(config_filename)
        if not config_path.exists():
            errors.append(logging.LogRecord(logging.WARN, 400, 'config_load', f"File '{config_filename}' does not exist"))
        else:
            with open(config_filename, 'r') as file:
                try:
                    # Load and parse the configuration file here
                    # For this example, let's assume the content is parsed as a dictionary
                    parsed_config = file.read()
                    configurations[config_filename] = parsed_config
                except Exception as e:
                    errors.append(logging.LogRecord(logging.ERROR, 500, 'config_load', f"Error loading file '{config_filename}': {e}"))

    if overrides:
        try:
            # Apply overrides here
            # For this example, let's assume overrides are applied to the configurations dictionary
            modified_configurations = {**configurations, **overrides}
        except Exception as e:
            errors.append(logging.LogRecord(logging.ERROR, 500, 'config_load', f"Error applying overrides: {e}"))

    return modified_configurations if overrides else configurations, errors

