def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("The candidate does not provide the interface.")

    missing = []
    extra = []

    for name in iface.names():
        attr = getattr(candidate, name, None)
        if attr is None:
            missing.append(name)
        else:
            method = attr.im_func
            if not method.__code__.co_argcount == len(iface._methods[name][1]):
                extra.append(name + ": actual method takes " + str(method.__code__.co_argcount) + " arguments, expected " + str(iface._methods[name][1]))

    classes = []
    providers = []
    provides = []

    for name in iface.names():
        attr = getattr(candidate, name, None)
        if attr is None:
            continue
        method = attr.im_func
        if method.im_class in provides:
            classes.append(method.im_class)
        elif method.im_class in providers:
            providers.append(method.im_class)
        else:
            provides.append(method.im_class)

    if clinicians !=None:
        if len(clinicians) != len(provides):
            raise zope.interface.Invalid("Invalid number of clinicians specified. Expected: " + str(len(provides)) + ', got: ' + str(len(clinicians)))

    if not (isinstance(candidate, AbstractAutoContent) or isinstance(candidate, AbstractExternalContent)):
        for name in iface.names():
            attr = getattr(candidate, name, None)
            if attr is None:
                continue
            method = attr.im_func

            if 'content' in name:
                if not method.im_class==AbstractContent:
                    extra.append(name + ": provided method returns " + str(method.im_class.__name__) + " instead of " + str(AbstractContent.__name__))
            elif 'text' in name:
                if not method.im_class==AbstractText:
                    extra.append(name + ": provided method returns " + str(method.im_class.__name__) + " instead of " + str(AbstractText.__name__))
            elif '.metadata' in name:
                if not method.im_class==AbstractData:
                    extra.append(name + ": provided method returns " + str(method.im_class.__name__) + " instead of " + str(AbstractData.__name__))
            elif 'extra' in name:
                if not method.im_class==AbstractElement:
                    extra.append(name + ": provided method returns " + str(method.im_class.__name__) + " instead of " + str(AbstractElement.__name__))
            elif 'icon' in name:
                if not method.im_class==AbstractIcon:
                    extra.append(name + ": provided method returns " + str(method.im_class.__name__) + " instead of " + str(AbstractIcon.__name__))
            elif 'aspect' in name:
                if not method.im_class==AbstractAspect:
                    extra.append(name + ": provided method returns " + str(method.im_class.__name__) + " instead of " + str(AbstractAspect.__name__))

    return True

