def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
        import dateutil.parser

        def _parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
            if isinstance(timestr, str):
                return dateutil.parser.parse(timestr, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)
            elif timestr is None:
                return default
            else:
                raise TypeError("Invalid input type")

        date = _parse(timestr, default, ignoretz, tzinfos, **kwargs)
        if kwargs.get('fuzzy_with_tokens'):
            match_obj = dateutil.parser.parse(timestr, fuzzy=True, tzinfos=tzinfos, **kwargs)
            tokens = match_obj.tokens
            return date, tokens
        else:
            return date

def identify_request(request: RequestType):
        """Try to identify whether this is a Diaspora request.

        Try first public message. Then private message. The check if this is a legacy payload.
        """
        if isinstance(request, PublicMessage):
            return "diaspora_public"
        elif isinstance(request, PrivateMessage):
            return "diaspora_private"
        elif isinstance(request, LegacyPayload):
            return "diaspora_legacy"
        else:
            raise ValueError("Unsupported request type")

if hasattr(request, 'matrixRequest') and request.matrixRequest:
        return True
    return False

