import requests
from typing import Optional

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        response = requests.head(url)
        return response.headers.get('Content-Type', None)
    except requests.exceptions.RequestException as e:
        print(f"Error fetching content type: {e}")
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    return tag.isalnum()

def xml_children_as_dict(node):
    children_dict = {}
    for child in node.childNodes:
        if child.nodeType == child.ELEMENT_NODE:
            tag_name = child.tagName
            if tag_name not in children_dict:
                children_dict[tag_name] = []
            children_dict[tag_name].append({
                'name': child.tagName,
                'attrs': child.attributestostring(),
                'text': child.firstChild.nodeValue if child.firstChild is not None else None
            })
    return children_dict

