    if yaml_file is None:
        raise ValueError("No YAML file provided")
    with open(yaml_file, 'r') as file:
        data = yaml.safe_load(file)

    # Check if all required fields are present
    required_fields = set(data.keys()) & {'name', 'age', 'email'}
    if not required_fields:
        raise IRValidatorException("Mandatory data is missing in the file")

    for field in required_fields:
        if field not in data or not data[field]:
            raise IRValidatorException(f"The field '{field}' is missing in the file")

    return data

