def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    for arg in args:
        if "__ir__" in arg:
            control_args[argName(arg)] = arg
        elif "__ansible__" in arg:
            nested_args[argName(arg)] = arg
        else:
            raise ValueError(f"Unknown argument type: {argName(arg)}")

    return control_args, nested_args


def argName(arg):
    """Remove the prefix '__anm' and remove '_'. Just return the name"""
    return arg[len('__anm'):-1] if arg.startswith('__anm') else arg


def isIrArgument(arg):
    """Determine if the argument is a control argument or a nested argument."""
    return "__ir__" in arg or "__ansible__" in arg

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        try:
            if value is not None:
                type_ = type(value)
                if type_ == str:
                    values_dict[key] = float(value) if '.' in value else int(value)
                elif type_ in [float, int]:
                    values_dict[key] = type_(value)
            else:
                values_dict[key] = None
        except ValueError:
            if parser_name == 'main':
                print(f"Failed to parse value '{value}' for argument '{key}' for command '{parser_name}'. Using default value.")
            else:
                print(f"Failed to parse value '{value}' for argument '{key}' for command '{parser_name}'.")

def strip_root(self, path, root):
        """Remove root from path, throw exception on failure."""
        if not path.startswith(root):
            raise ValueError("Path {0} does not start with root {1}".format(path, root))
        return path[len(root):]
